import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_conv1_cuda = load_inline(
    name="conv1_custom_cuda",
    cpp_sources=r"""
#include <torch/extension.h>

torch::Tensor conv_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding);

""",
    cuda_sources=r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void conv2d_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int n,
    int in_channels,
    int in_height,
    int in_width,
    int out_channels,
    int out_height,
    int out_width,
    int kernel_height,
    int kernel_width,
    int stride,
    int padding) {
    const int spatial_index = blockIdx.x;
    const int oh = spatial_index / out_width;
    const int ow = spatial_index - oh * out_width;
    const int batch = blockIdx.y;

    extern __shared__ float input_tile[];

    const int kernel_area = kernel_height * kernel_width;
    const int input_tile_size = in_channels * kernel_area;

    for (int linear = threadIdx.x; linear < input_tile_size; linear += blockDim.x) {
        const int c = linear / kernel_area;
        const int rem = linear - c * kernel_area;
        const int kh = rem / kernel_width;
        const int kw = rem - kh * kernel_width;

        const int ih = oh * stride - padding + kh;
        const int iw = ow * stride - padding + kw;

        float value = 0.0f;
        if (ih >= 0 && ih < in_height && iw >= 0 && iw < in_width) {
            const int input_index =
                ((batch * in_channels + c) * in_height + ih) * in_width + iw;
            value = static_cast<float>(input[input_index]);
        }

        input_tile[linear] = value;
    }

    __syncthreads();

    const int oc = threadIdx.x;
    if (oc < out_channels) {
        float acc = static_cast<float>(bias[oc]);

        const int weight_base = oc * input_tile_size;
        for (int k = 0; k < input_tile_size; ++k) {
            acc += input_tile[k] * static_cast<float>(weight[weight_base + k]);
        }

        const int output_index =
            ((batch * out_channels + oc) * out_height + oh) * out_width + ow;
        output[output_index] = static_cast<scalar_t>(acc);
    }
}

torch::Tensor conv_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");

    TORCH_CHECK(input.dim() == 4, "input must be 4D NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D OIHW");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");

    TORCH_CHECK(input.scalar_type() == weight.scalar_type(),
                "input and weight must have the same dtype");
    TORCH_CHECK(input.scalar_type() == bias.scalar_type(),
                "input and bias must have the same dtype");

    auto input_contig = input.contiguous();
    auto weight_contig = weight.contiguous();
    auto bias_contig = bias.contiguous();

    const int batch = static_cast<int>(input_contig.size(0));
    const int in_channels = static_cast<int>(input_contig.size(1));
    const int in_height = static_cast<int>(input_contig.size(2));
    const int in_width = static_cast<int>(input_contig.size(3));

    const int out_channels = static_cast<int>(weight_contig.size(0));
    const int kernel_height = static_cast<int>(weight_contig.size(2));
    const int kernel_width = static_cast<int>(weight_contig.size(3));

    TORCH_CHECK(weight_contig.size(1) == in_channels,
                "weight input channels do not match input");
    TORCH_CHECK(bias_contig.size(0) == out_channels,
                "bias size does not match output channels");

    const int out_height =
        (in_height + 2 * static_cast<int>(padding) - kernel_height) /
            static_cast<int>(stride) +
        1;
    const int out_width =
        (in_width + 2 * static_cast<int>(padding) - kernel_width) /
            static_cast<int>(stride) +
        1;

    TORCH_CHECK(out_height > 0 && out_width > 0,
                "invalid convolution output dimensions");

    auto output = torch::empty(
        {batch, out_channels, out_height, out_width},
        input_contig.options());

    const int blocks = batch * out_height * out_width;
    const int threads = 128;
    const size_t shared_bytes =
        static_cast<size_t>(in_channels) *
        static_cast<size_t>(kernel_height) *
        static_cast<size_t>(kernel_width) *
        sizeof(float);

    dim3 grid(static_cast<unsigned int>(out_height * out_width),
              static_cast<unsigned int>(batch),
              1);
    dim3 block(threads, 1, 1);

    cudaStream_t stream = at::cuda::getDefaultCUDAStream();

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        input_contig.scalar_type(),
        "conv2d_custom_cuda",
        [&] {
            conv2d_kernel<scalar_t><<<grid, block, shared_bytes, stream>>>(
                input_contig.data_ptr<scalar_t>(),
                weight_contig.data_ptr<scalar_t>(),
                bias_contig.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                batch,
                in_channels,
                in_height,
                in_width,
                out_channels,
                out_height,
                out_width,
                kernel_height,
                kernel_width,
                static_cast<int>(stride),
                static_cast<int>(padding));
        });

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
""",
    functions=["conv_forward"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(
            in_channels=3,
            out_channels=96,
            kernel_size=11,
            stride=4,
            padding=2,
        )

    def forward(self, x):
        return _conv1_cuda.conv_forward(
            x,
            self.conv1.weight,
            self.conv1.bias,
            self.conv1.stride[0],
            self.conv1.padding[0],
        )

